  int SeparatorY(){if(Project==null)return -1;var video=Tracks().Where(t=>t.kind=="video").ToList();if(video.Count==0||!Tracks().Any(t=>t.kind=="audio"))return -1;int natural=32+video.Sum(t=>TrackRowHeight(t));return Math.Max(80,Math.Min(Math.Max(80,Height-75),splitY<0?natural:splitY));}
  Rectangle TrackViewport(string kind){int split=SeparatorY();return split<0?new Rectangle(0,32,Width,Math.Max(0,Height-32)):kind=="video"?new Rectangle(0,32,Width,Math.Max(0,split-32)):new Rectangle(0,split,Width,Math.Max(0,Height-split));}
  public int TrackTop(string id){if(Project==null)return -10000;var track=Project.Active.tracks.Find(t=>t.id==id);if(track==null)return -10000;var group=Tracks().Where(t=>t.kind==track.kind).ToList();int total=group.Sum(t=>TrackRowHeight(t));int y=track.kind=="video"?SeparatorY()-total+videoVertical:SeparatorY()-audioVertical;foreach(var t in group){if(t.id==id)return y;y+=TrackRowHeight(t);}return -10000;}
