  public string NewTrackDropAt(Point point,string kind){if(Project==null||point.X<=headerWidth||point.Y<0||point.Y>=Height)return null;if(kind=="video"){if(point.Y<32)return NewVideoTrackDrop;var view=TrackViewport("video");var first=Tracks().FirstOrDefault(t=>t.kind=="video");return first!=null&&point.Y>=view.Top&&point.Y<Math.Min(view.Bottom,Math.Max(view.Top+16,TrackTop(first.id)+16))?NewVideoTrackDrop:null;}if(kind=="audio"){var view=TrackViewport("audio");var last=Tracks().LastOrDefault(t=>t.kind=="audio");int visibleBottom=last==null?view.Top:Math.Min(view.Bottom,TrackTop(last.id)+TrackHeight(last.id));return last!=null&&point.Y>=Math.Max(view.Top,visibleBottom-20)&&point.Y<view.Bottom?NewAudioTrackDrop:null;}return null;}
