  public void RevealTrack(string id){var track=Tracks().Find(t=>t.id==id);if(track==null)return;var view=TrackViewport(track.kind);int top=TrackTop(id),bottom=top+TrackRowHeight(track);int overflow=Math.Max(0,Tracks().Where(t=>t.kind==track.kind).Sum(t=>TrackRowHeight(t))-view.Height);if(track.kind=="video"){if(top<view.Top)videoVertical=Math.Min(overflow,videoVertical+view.Top-top);else if(bottom>view.Bottom)videoVertical=Math.Max(0,videoVertical-(bottom-view.Bottom));Vertical=videoVertical;}else{if(top<view.Top)audioVertical=Math.Max(0,audioVertical-(view.Top-top));else if(bottom>view.Bottom)audioVertical=Math.Min(overflow,audioVertical+bottom-view.Bottom);Vertical=audioVertical;}SyncVerticalScrollbars();Invalidate();}
