  public RectangleF ClipBounds(Clip clip){return new RectangleF(X(clip.timeline_start.Seconds),TrackTop(clip.track_id),Math.Max(1,(float)(clip.duration.Seconds*Zoom)),TrackHeight(clip.track_id));}
  public static double SourceTime(Clip clip,double timelineTime){return clip.source_in.Seconds+(timelineTime-clip.timeline_start.Seconds)*clip.speed.Seconds;}
  void DrawWaveform(Graphics g,Clip clip,RectangleF bounds,WaveformData peaks,bool active){
   if(peaks==null||bounds.Height<24||peaks.Count==0)return;
   var track=Project.Active.tracks.Find(t=>t.id==clip.track_id);
   float top=bounds.Top+(TrackPresentation.ShowNames(Project.Active,track)?19:4),bottom=bounds.Bottom-3;
   if(bottom-top<2)return;
   int left=Math.Max(headerWidth+1,(int)Math.Ceiling(bounds.Left+HandleWidth(clip)));
   int right=Math.Min(Width-1,(int)Math.Floor(bounds.Right-HandleWidth(clip)));
   float middle=(top+bottom)/2,half=(bottom-top)/2;
   double gain=Math.Pow(10.0,(clip.gain_db+(track==null?0:track.gain_db))/20.0);
   Color background=ClipLabels.ColorFor(clip,"audio");
   int luminance=(background.R*3+background.G*6+background.B)/10;
   Color ink=luminance>=150?Color.FromArgb(active?200:90,27,54,75):Color.FromArgb(active?205:95,239,248,252);
   using(var pen=new Pen(ink)){
    for(int x=left;x<right;x++){
     double start=Math.Max(clip.timeline_start.Seconds,(x-headerWidth)/Zoom+Scroll);
     double end=Math.Min(clip.End,(x+1-headerWidth)/Zoom+Scroll);
     int first=(int)Math.Floor(SourceTime(clip,start)*peaks.BinsPerSecond);
     int last=(int)Math.Ceiling(SourceTime(clip,end)*peaks.BinsPerSecond);
     first=Math.Max(0,first);last=Math.Min(peaks.Count,Math.Max(first+1,last));
     if(first>=peaks.Count||last<=first)continue;
     short low=short.MaxValue,high=short.MinValue;
     for(int i=first;i<last;i++){if(peaks.Minimum[i]<low)low=peaks.Minimum[i];if(peaks.Maximum[i]>high)high=peaks.Maximum[i];}
     float upper=(float)Math.Max(-1,Math.Min(1,high/32768.0*gain));
     float lower=(float)Math.Max(-1,Math.Min(1,low/32768.0*gain));
     g.DrawLine(pen,x,middle-upper*half,x,middle-lower*half);
    }
   }
  }
  void DrawShortTail(Graphics graphics,Clip clip,RectangleF bounds){
   double? start=ShortTail.MissingStart(Project,clip);if(!start.HasValue)return;
   float left=Math.Max(Math.Max(bounds.Left,X(start.Value)),headerWidth+1),right=Math.Min(bounds.Right,Width-1);
   if(right<=left)return;
   var tail=RectangleF.FromLTRB(left,bounds.Top,right,bounds.Bottom);
   using(var hatch=new HatchBrush(HatchStyle.ForwardDiagonal,Color.FromArgb(225,255,123,112),Color.FromArgb(215,68,42,48)))graphics.FillRectangle(hatch,tail);
   using(var border=new Pen(Color.FromArgb(240,255,161,147),1.5f))graphics.DrawLine(border,left,bounds.Top,left,bounds.Bottom);
  }
  static Color EditGroupColor(int number){Color[] colors={Color.FromArgb(91,199,240),Color.FromArgb(143,219,130),Color.FromArgb(241,192,83),Color.FromArgb(217,141,222),Color.FromArgb(243,127,125),Color.FromArgb(105,220,193),Color.FromArgb(170,173,247),Color.FromArgb(235,159,103),Color.FromArgb(191,220,95),Color.FromArgb(228,139,180)};return colors[(number-1)%colors.Length];}
  void DrawEditGroups(Graphics graphics){
   foreach(var group in Project.Active.edit_groups){Color tint=EditGroupColor(group.number);bool hover=group.id==hoveredEditGroupId;
    foreach(string clipId in group.clip_ids){var clip=Project.Active.clips.Find(c=>c.id==clipId);if(clip==null||!TrackVisible(clip.track_id))continue;var track=Project.Active.tracks.Find(t=>t.id==clip.track_id);var bounds=ClipBounds(clip);if(bounds.Right<headerWidth||bounds.Left>Width)continue;var state=graphics.Save();graphics.SetClip(TrackViewport(track.kind),CombineMode.Intersect);
     if(hover)using(var wash=new SolidBrush(Color.FromArgb(42,tint)))graphics.FillRectangle(wash,bounds);
     using(var shadow=new Pen(Color.FromArgb(220,28,29,33),hover?6:5))graphics.DrawLine(shadow,bounds.Left+2,bounds.Bottom-3,bounds.Right-2,bounds.Bottom-3);
     using(var stripe=new Pen(tint,hover?4:3))graphics.DrawLine(stripe,bounds.Left+3,bounds.Bottom-3,bounds.Right-3,bounds.Bottom-3);
     string label="G"+group.number;if(bounds.Width>=100){int labelWidth=TextRenderer.MeasureText(label,Font).Width+8;var rect=new Rectangle((int)bounds.Right-labelWidth-5,(int)bounds.Top+5,labelWidth,17);using(var back=new SolidBrush(Color.FromArgb(230,34,36,41)))graphics.FillRectangle(back,rect);TextRenderer.DrawText(graphics,label,Font,rect,tint,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);}
     graphics.Restore(state);
    }
   }
  }
  public float HandleWidth(Clip clip){return Math.Min(10,ClipBounds(clip).Width*0.20f);}
  public float RollHandleRadius(Track track){return Math.Min(14,Math.Max(6,(TrackHeight(track.id)-8)*0.20f));}
  public int ClipActionAt(Clip clip,float x){var r=ClipBounds(clip);float handle=HandleWidth(clip);return x<r.Left+handle?1:x>=r.Right-handle?2:0;}
  List<string> GroupSelection(string clipId){var ids=new HashSet<string>{clipId};bool changed;do{int count=ids.Count;foreach(var group in Project.Active.edit_groups.Where(g=>g.clip_ids.Any(ids.Contains)))foreach(string id in group.clip_ids)ids.Add(id);foreach(var group in Project.Active.link_groups.Where(g=>g.clip_ids.Any(ids.Contains)))foreach(string id in group.clip_ids)ids.Add(id);changed=ids.Count!=count;}while(changed);return Project.Active.clips.Where(c=>ids.Contains(c.id)).Select(c=>c.id).ToList();}
  Clip HitClip(Point point,Track track){return track==null?null:Project.Active.clips.LastOrDefault(c=>c.track_id==track.id&&point.X>=ClipBounds(c).Left&&point.X<ClipBounds(c).Right);}
  public Tuple<Clip,Clip> RollPairAt(Point point,Track track){
   if(track==null||track.locked||point.X<headerWidth)return null;
   var clips=Project.Active.clips.Where(c=>c.track_id==track.id).OrderBy(c=>c.timeline_start.Seconds).ToList();
   for(int i=0;i+1<clips.Count;i++){
    var left=clips[i];var right=clips[i+1];
    if(Math.Abs(left.End-right.timeline_start.Seconds)>0.000001)continue;
    var a=ClipBounds(left);var b=ClipBounds(right);
    float radius=RollHandleRadius(track);
    float lower=a.Bottom-Math.Max(12,Math.Min(20,a.Height/3));
    if(Math.Abs(point.X-X(left.End))<=radius&&point.Y>=lower+2&&point.Y<a.Bottom-2)
     return Tuple.Create(left,right);
   }
   return null;
  }
  void BeginRollGesture(Clip left,Clip right,Track track,MouseEventArgs e){
   SelectedGapTrack=null;dragging=left.id;rollLeft=left.id;rollRight=right.id;mode=3;altDrag=(CurrentModifiers&Keys.Alt)!=0;
   oldStart=left.End;oldEnd=left.End;dragTime=oldEnd;dragTrack=track.id;origin=e.Location;dragMoved=false;
   gestureTool=EffectiveTool;Capture=true;Invalidate();
  }
  void BeginEdgeGesture(Clip clip,Track track,MouseEventArgs e){
   SelectedGapTrack=null;Selected=clip.id;controlDown=(CurrentModifiers&Keys.Control)!=0;
   controlBase=Selection.ToList();insertDrag=false;altDrag=(CurrentModifiers&Keys.Alt)!=0;
   if(altDrag)Selection=new List<string>{clip.id};
   else if(controlDown){Selection=controlBase.Concat(GroupSelection(clip.id)).Distinct().ToList();}
   else if(!Selection.Contains(clip.id))Selection=GroupSelection(clip.id);else Selection=Selection.Concat(GroupSelection(clip.id)).Distinct().ToList();
   if(SelectionChanged!=null)SelectionChanged(clip.id);
    dragging=clip.id;ghostTrack=null;origin=e.Location;dragMoved=false;
   rippleTrim=controlDown&&!temporarySelect&&gestureTool==ToolMode.Select;
   oldStart=clip.timeline_start.Seconds;oldEnd=clip.End;oldSource=clip.source_in.Seconds;oldSpeed=clip.speed.Seconds;
   mode=ClipActionAt(clip,e.X);dragTime=mode==2?oldEnd:oldStart;dragTrack=track.id;base.Cursor=Cursors.SizeWE;Capture=true;Invalidate();
  }
  bool CanSlip(Clip clip){var asset=Project.assets.Find(a=>a.id==clip.asset_id);var stream=asset==null?null:asset.streams.Find(s=>s.id==clip.stream_id);return stream!=null&&stream.kind!="image";}
  bool GapAt(string trackId,double time,out double from,out double to){from=to=0;if(Project==null||trackId==null)return false;var clips=Project.Active.clips.Where(c=>c.track_id==trackId).OrderBy(c=>c.timeline_start.Seconds).ToList();var left=clips.LastOrDefault(c=>c.End<=time+0.000001);var right=clips.FirstOrDefault(c=>c.timeline_start.Seconds>=time-0.000001);if(left==null||right==null||right.timeline_start.Seconds<=left.End+0.000001)return false;from=left.End;to=right.timeline_start.Seconds;return time>=from-0.000001&&time<=to+0.000001;}
  public void ClearInvalidEditCues(){if(Project==null)return;double from,to;if(SelectedGapTrack!=null&&(!GapAt(SelectedGapTrack,(SelectedGapStart+SelectedGapEnd)/2,out from,out to)||Math.Abs(from-SelectedGapStart)>0.000001||Math.Abs(to-SelectedGapEnd)>0.000001))SelectedGapTrack=null;if(SelectedJunctionLeft!=null){var left=Project.Active.clips.Find(c=>c.id==SelectedJunctionLeft);var right=Project.Active.clips.Find(c=>c.id==SelectedJunctionRight);if(left==null||right==null||left.track_id!=right.track_id||Math.Abs(left.End-right.timeline_start.Seconds)>0.000001)ClearJunctionSelection();}if(rollLeft!=null&&!Project.Active.clips.Any(c=>c.id==rollLeft)){rollLeft=rollRight=null;hoverRollLeft=hoverRollRight=null;}}

