  public void EnsureCursor(){double span=Math.Max(1,(Width-headerWidth)/Zoom);if(Cursor<Scroll)Scroll=Math.Max(0,Cursor-span*0.1);else if(Cursor>=Scroll+span)Scroll=Math.Max(0,Cursor-span*0.7);Invalidate();}
  double Adjust(double time){time=Rational.Frame(time).Seconds;if(!Snap||Project==null)return time;var excluded=new HashSet<string>(Selection);if(dragging!=null)excluded.Add(dragging);if(!altDrag)foreach(var group in Project.Active.link_groups.Where(g=>g.clip_ids.Any(excluded.Contains)))foreach(string id in group.clip_ids)excluded.Add(id);var values=Project.Active.clips.Where(c=>!excluded.Contains(c.id)).SelectMany(c=>new[]{c.timeline_start.Seconds,c.End}).Concat(Markers.Read(Project.Active).Select(marker=>marker.Seconds)).Concat(new[]{Cursor,0.0});double near=values.OrderBy(x=>Math.Abs(x-time)).First();return Math.Abs(near-time)*Zoom<8?near:time;}
  public double AdjustMove(double proposedStart,string anchorId){
   proposedStart=Rational.Frame(Math.Max(0,proposedStart)).Seconds;
   if(!Snap||Project==null)return proposedStart;
   var anchor=Project.Active.clips.Find(c=>c.id==anchorId);if(anchor==null)return proposedStart;
   var moving=new HashSet<string>(Selection.Contains(anchorId)?Selection:new List<string>{anchorId});
   if(!altDrag)foreach(var group in Project.Active.link_groups.Where(g=>g.clip_ids.Any(moving.Contains)))foreach(string id in group.clip_ids)moving.Add(id);
   var movingClips=Project.Active.clips.Where(c=>moving.Contains(c.id)).ToList();
   double shift=proposedStart-anchor.timeline_start.Seconds;
   var movingEdges=movingClips.SelectMany(c=>new[]{c.timeline_start.Seconds+shift,c.End+shift}).ToList();
   var fixedEdges=Project.Active.clips.Where(c=>!moving.Contains(c.id)).SelectMany(c=>new[]{c.timeline_start.Seconds,c.End}).Concat(Markers.Read(Project.Active).Select(marker=>marker.Seconds)).Concat(new[]{Cursor,0.0});
   double best=8/Zoom,offset=0;
   foreach(double fixedEdge in fixedEdges)foreach(double movingEdge in movingEdges){double delta=fixedEdge-movingEdge;if(Math.Abs(delta)<best){best=Math.Abs(delta);offset=delta;}}
   return Rational.Frame(Math.Max(0,proposedStart+offset)).Seconds;
  }
