  public static bool IsDirection(ToolMode mode){return mode==ToolMode.TrackForward||mode==ToolMode.TrackBackward||mode==ToolMode.TrackUp||mode==ToolMode.TrackDown||mode==ToolMode.TrackAll;}
  public void SelectDirection(string trackId,double time,bool forward,bool allTracks,bool ignoreLinks){SelectArea(trackId,time,forward?ToolMode.TrackForward:ToolMode.TrackBackward,allTracks,ignoreLinks);}
  public void SelectArea(string trackId,double time,ToolMode direction,bool allTracks,bool ignoreLinks){
   if(Project==null||!IsDirection(direction))return;
   var tracks=Tracks();int anchor=tracks.FindIndex(t=>t.id==trackId);if(anchor<0)return;
   var scope=new HashSet<string>();
   for(int i=0;i<tracks.Count;i++)if(direction==ToolMode.TrackAll||direction==ToolMode.TrackUp&&i<=anchor||direction==ToolMode.TrackDown&&i>=anchor||(direction==ToolMode.TrackForward||direction==ToolMode.TrackBackward)&&(allTracks||i==anchor))scope.Add(tracks[i].id);
   var ids=new HashSet<string>(Project.Active.clips.Where(c=>scope.Contains(c.track_id)&&(direction==ToolMode.TrackForward?c.End>time+0.000001:direction==ToolMode.TrackBackward?c.timeline_start.Seconds<time-0.000001:true)).Select(c=>c.id));
   if(!ignoreLinks)foreach(var group in Project.Active.link_groups.Where(g=>g.clip_ids.Any(ids.Contains)))foreach(string id in group.clip_ids)ids.Add(id);
   Selection=Project.Active.clips.Where(c=>ids.Contains(c.id)).OrderBy(c=>c.timeline_start.Seconds).ThenBy(c=>tracks.FindIndex(t=>t.id==c.track_id)).Select(c=>c.id).ToList();
   Selected=Selection.FirstOrDefault();SelectedGapTrack=null;
   if(SelectionChanged!=null)SelectionChanged(Selected);Invalidate();
  }
  void BeginDirectionDrag(Track track,MouseEventArgs e){
   if(Selection.Count==0)return;
   var hit=Project.Active.clips.LastOrDefault(c=>c.track_id==track.id&&ClipBounds(c).Contains(e.Location)&&Selection.Contains(c.id));
   var anchor=hit??Project.Active.clips.Find(c=>c.id==Selected);if(anchor==null)return;
   dragging=anchor.id;directionalDrag=true;gestureTool=ToolMode.Select;controlDown=false;dragMoved=false;insertDrag=false;altDrag=(CurrentModifiers&Keys.Alt)!=0;
   origin=e.Location;oldStart=anchor.timeline_start.Seconds;oldEnd=anchor.End;oldSource=anchor.source_in==null?0:anchor.source_in.Seconds;oldSpeed=anchor.speed==null?1:anchor.speed.Seconds;
   dragTime=oldStart;dragTrack=anchor.track_id;ghostTrack=null;mode=0;rippleTrim=false;Capture=true;
  }
  bool CanPreviewGroupAt(string targetTrackId){
   var anchor=Project.Active.clips.Find(c=>c.id==dragging);if(anchor==null)return false;
   var source=Project.Active.tracks.Find(t=>t.id==anchor.track_id);
   var destination=Project.Active.tracks.Find(t=>t.id==targetTrackId);
   if(source==null||destination==null||source.kind!=destination.kind||destination.locked)return false;
   int shift=destination.order-source.order;
   return Project.Active.clips.Where(c=>Selection.Contains(c.id)).All(c=>{
